from itertools import product
cnt = 0
for per in product('01234567', repeat=7):
    num = ''.join(per)
    if num[0] != '0':
        if len([x for x in num if x in '02468']) == 2:
            if all(pair not in num for pair in '71 17 37 73 57 75 77'.split()):
                cnt += 1
print(cnt)

